    'grocery@roxiler.com',
    '202 Market Street, Market City, MC 65432',
    (SELECT id FROM users WHERE email = 'owner2@roxiler.com' LIMIT 1)
ON CONFLICT (email) DO NOTHING;

-- Sample Ratings (user1 rated electronics store 5 stars, user2 rated 4 stars, etc.)
INSERT INTO ratings (id, user_id, store_id, rating)
SELECT
    uuid_generate_v4(),
    (SELECT id FROM users WHERE email = 'user1@roxiler.com' LIMIT 1),
    (SELECT id FROM stores WHERE email = 'electronics@roxiler.com' LIMIT 1),
    5
ON CONFLICT (user_id, store_id) DO UPDATE SET rating = EXCLUDED.rating;

